    user_id, comment_id, level, create_time, update_time, is_deleted
) VALUES (
    #{userId}, #{commentId}, #{level}, NOW(), NOW(), 0
)

mapper.select:
SELECT * FROM character_comment_like 
WHERE user_id = #{userId} 
  AND comment_id = #{commentId}
  AND level = #{level}
LIMIT 1

mapper.update:
